{
  "decision-wayfinding-sign-export-after-walkthrough": "WITH replacements AS (SELECT s.site_code, s.required_text, s.order_id, f.check_id FROM sign_order AS s JOIN field_check AS f USING (site_code) WHERE f.seen_text IS NULL OR f.seen_text COLLATE BINARY <> s.required_text), ordered AS (SELECT order_id, check_id, '\"' || replace(site_code, '\"', '\"\"') || '\",\"' || replace(required_text, '\"', '\"\"') || '\",\"' || replace(order_id, '\"', '\"\"') || '\",\"' || replace(check_id, '\"', '\"\"') || '\"' || char(10) AS csv_line FROM replacements ORDER BY site_code COLLATE BINARY ASC) SELECT group_concat(order_id, ',') AS order_id_set, group_concat(check_id, ',') AS check_id_set, 'site_code,required_text,order_id,check_id' || char(10) || group_concat(csv_line, '') AS csv_content FROM ordered",
  "decision-wheel-state-at-shutter-open": "SELECT f.frame_id, w.filter_code, w.source_id FROM frames AS f LEFT JOIN wheel_notes AS w ON (w.event_s, w.seq_no) = (SELECT n.event_s, n.seq_no FROM wheel_notes AS n WHERE n.event_kind = 'seated' AND n.event_s <= f.shutter_s ORDER BY n.event_s DESC, n.seq_no DESC LIMIT 1) ORDER BY f.frame_id ASC"
}
